pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: give the contract some ether so sendMoney works
        vm.deal(address(c), 1 ether);
        // Use a non-owner address to call sendMoney
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        // This will revert because onlyOwner, so no ether is sent
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", attacker, 1));
        // The call should fail (non-owner) – but the key is what happens to depositsCount
        // Since the call reverted, depositsCount should be unchanged in reference (0) but buggy may increment
        // Actually, sendMoney reverts before any ether transfer, so depositsCount stays 0 in both.
        // Need a different approach: first fund contract, then have owner call sendMoney to attacker
        // This will trigger receive() on the attacker, but the contract (not attacker) receives ether? No.
        // Better: fund the contract, then owner calls sendMoney to the contract itself – triggering receive()
        vm.deal(address(c), 1 ether);
        address owner = c.owner();
        vm.prank(owner);
        // Owner sends 1 wei to the contract itself – this triggers receive()
        c.sendMoney(address(c), 1);
        // After this, check depositsCount:
        // Reference: receive() executes require + increment => depositsCount = 1
        // Bug: receive() just increments => depositsCount = 1 as well? No difference.
        // Need to find a case where reference receive() reverts but bug doesn't.
        // Use overflow: if depositsCount = type(uint).max, reference require fails, bug passes
        vm.store(address(c), bytes32(uint(1)), bytes32(type(uint).max)); // depositsCount is slot 1
        vm.prank(owner);
        // This will revert in reference because (type(uint).max + 1) < type(uint).max
        // but bug will succeed and increment to 0
        (bool ok, ) = address(c).call{value: 1}("");
        assertTrue(ok == false); // reference reverts (ok false); bug passes (ok true) – difference!
    }
}

